import React from 'react';
import ReactDOM from 'react-dom/client';
import { HashRouter } from 'react-router-dom';
import './index.css';
import App from './App';
import reportWebVitals from './reportWebVitals';

// Conditionally import TestApp (for test mode)
const TestApp = React.lazy(() => import('./test/TestApp'));

// Determine if we should render in test mode
const isTestMode = window.testRender || new URLSearchParams(window.location.search).has('test');

// Create root element based on mode
const rootElement = document.getElementById(isTestMode ? 'test-root' : 'root');

// Only render if we have a valid root element
if (rootElement) {
  const root = ReactDOM.createRoot(rootElement);
  
  root.render(
    <React.StrictMode>
      {isTestMode ? (
        <React.Suspense fallback={<div>Loading test environment...</div>}>
          <TestApp />
        </React.Suspense>
      ) : (
        <HashRouter>
          <App />
        </HashRouter>
      )}
    </React.StrictMode>
  );
}

// Report web vitals
reportWebVitals();
