import React, { createContext, useContext, useState, useEffect } from 'react';

// Create auth context
const AuthContext = createContext();

// Auth provider component
export const AuthProvider = ({ children }) => {
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isNewUser, setIsNewUser] = useState(false);
  const [onboardingCompleted, setOnboardingCompleted] = useState(false);

  // Load user from localStorage on initial render
  useEffect(() => {
    const storedUser = localStorage.getItem('user');
    const storedOnboarding = localStorage.getItem('onboardingCompleted');
    
    if (storedUser) {
      try {
        const parsedUser = JSON.parse(storedUser);
        
        // Ensure user has the required properties
        const userWithDefaults = {
          ...parsedUser,
          studyData: Array.isArray(parsedUser.studyData) ? parsedUser.studyData : [],
          tasks: Array.isArray(parsedUser.tasks) ? parsedUser.tasks : [],
          streakDays: typeof parsedUser.streakDays === 'number' ? parsedUser.streakDays : 0,
          gender: parsedUser.gender || 'neutral', // Default gender if not set
          customAvatar: parsedUser.customAvatar || null // Support for custom avatar
        };
        
        setCurrentUser(userWithDefaults);
      } catch (error) {
        console.error('Error parsing stored user:', error);
        localStorage.removeItem('user'); // Clear invalid data
      }
    }
    
    if (storedOnboarding) {
      try {
        setOnboardingCompleted(JSON.parse(storedOnboarding));
      } catch (error) {
        console.error('Error parsing stored onboarding status:', error);
        localStorage.removeItem('onboardingCompleted'); // Clear invalid data
      }
    }
    
    setLoading(false);
  }, []);

  // Update user data function (for tasks, study data, etc.)
  const updateUserData = (data) => {
    if (!currentUser) return false;
    
    const updatedUser = {
      ...currentUser,
      ...data
    };
    
    setCurrentUser(updatedUser);
    localStorage.setItem('user', JSON.stringify(updatedUser));
    return true;
  };

  // Update user tasks specifically
  const updateTasks = (tasks) => {
    if (!currentUser) return false;
    
    // Ensure tasks is always an array 
    const safeTasks = Array.isArray(tasks) ? tasks : [];
    
    // Create a new user object with updated tasks
    const updatedUser = {
      ...currentUser,
      tasks: safeTasks
    };
    
    // Update state and localStorage
    setCurrentUser(updatedUser);
    localStorage.setItem('user', JSON.stringify(updatedUser));
    
    console.log('Tasks updated:', safeTasks.length);
    return true;
  };

  // Update streak days specifically
  const updateStreak = (streakDays) => {
    if (!currentUser) return false;
    
    // Ensure streakDays is a number
    const safeStreak = typeof streakDays === 'number' ? streakDays : 0;
    
    // Create a new user object with updated streak
    const updatedUser = {
      ...currentUser,
      streakDays: safeStreak
    };
    
    // Update state and localStorage
    setCurrentUser(updatedUser);
    localStorage.setItem('user', JSON.stringify(updatedUser));
    
    console.log('Streak updated to:', safeStreak);
    return true;
  };

  // Add study session data
  const updateStudyData = (studySession) => {
    if (!currentUser) return false;
    
    // Create a session object with timestamp if not provided
    const newSession = {
      ...studySession,
      date: studySession.date || new Date().toISOString(),
      id: Math.random().toString(36).substr(2, 9) // Generate a simple ID
    };
    
    // Get current study data array or create empty one
    const currentStudyData = Array.isArray(currentUser.studyData) ? [...currentUser.studyData] : [];
    
    // Add new session to the array
    const updatedStudyData = [...currentStudyData, newSession];
    
    // Create a new user object with updated study data
    const updatedUser = {
      ...currentUser,
      studyData: updatedStudyData
    };
    
    // Update state and localStorage
    setCurrentUser(updatedUser);
    localStorage.setItem('user', JSON.stringify(updatedUser));
    
    console.log('Study data updated, sessions:', updatedStudyData.length);
    return true;
  };

  // Login function
  const login = (userData) => {
    // In a real app, this would validate credentials with an API
    const userWithRequiredFields = {
      ...userData,
      studyData: userData.studyData || [],
      tasks: userData.tasks || [],
      streakDays: userData.streakDays || 0,
      gender: userData.gender || 'neutral',
      customAvatar: userData.customAvatar || null
    };
    
    setCurrentUser(userWithRequiredFields);
    localStorage.setItem('user', JSON.stringify(userWithRequiredFields));
    
    // Check if this is a registered user but hasn't completed onboarding
    const userOnboardingStatus = localStorage.getItem(`onboarding_${userData.email}`);
    if (!userOnboardingStatus) {
      setIsNewUser(true);
      return { success: true, requiresOnboarding: true };
    }
    
    return { success: true, requiresOnboarding: false };
  };

  // Signup function
  const signup = (userData) => {
    // In a real app, this would create a new user via API
    const userWithEmptyData = {
      ...userData,
      studyData: [],
      tasks: [],
      streakDays: 0,
      gender: userData.gender || 'neutral',
      customAvatar: null
    };
    
    setCurrentUser(userWithEmptyData);
    localStorage.setItem('user', JSON.stringify(userWithEmptyData));
    setIsNewUser(true);
    return { success: true, requiresOnboarding: true };
  };

  // Complete onboarding function
  const completeOnboarding = (userPreferences) => {
    if (!currentUser) return false;
    
    const updatedUser = {
      ...currentUser,
      ...userPreferences,
      studyData: [],        // Initialize empty studyData array
      tasks: [],            // Initialize empty tasks array
      streakDays: 0,        // Initialize streak days to 0
      gender: userPreferences.gender || currentUser.gender || 'neutral',
      customAvatar: userPreferences.customAvatar || currentUser.customAvatar || null
    };
    
    setCurrentUser(updatedUser);
    localStorage.setItem('user', JSON.stringify(updatedUser));
    localStorage.setItem(`onboarding_${updatedUser.email}`, 'true');
    localStorage.setItem('onboardingCompleted', 'true');
    setOnboardingCompleted(true);
    setIsNewUser(false);
    
    return true;
  };

  // Update avatar specifically
  const updateAvatar = (avatarData) => {
    if (!currentUser) return false;
    
    const updatedUser = {
      ...currentUser,
      ...avatarData
    };
    
    setCurrentUser(updatedUser);
    localStorage.setItem('user', JSON.stringify(updatedUser));
    return true;
  };

  // Logout function
  const logout = () => {
    setCurrentUser(null);
    setOnboardingCompleted(false);
    localStorage.removeItem('user');
  };

  const value = {
    currentUser,
    isNewUser,
    onboardingCompleted,
    login,
    signup,
    logout,
    completeOnboarding,
    updateUserData,
    updateTasks,
    updateStreak,
    updateAvatar,
    updateStudyData,
    loading
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

// Custom hook to use auth context
export const useAuth = () => {
  return useContext(AuthContext);
};

export default AuthContext; 